import React, { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";

function PaymentPage() {
  const navigate = useNavigate();
  const location = useLocation();

  const [paymentMethod, setPaymentMethod] = useState("");
  const [formData, setFormData] = useState({
    cardNumber: "",
    expiry: "",
    cvv: "",
    upiId: "",
    bankName: "",
    accountNumber: ""
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const validateCardNumber = (num) => {
    const onlyDigits = num.replace(/\D/g, ""); 
    return onlyDigits.length >= 13 && onlyDigits.length <= 19;
  };

  const validateExpiry = (exp) => {
    if (!/^\d{2}\/\d{2}$/.test(exp)) return false;
    const [month, year] = exp.split("/").map(Number);
    if (month < 1 || month > 12) return false;

    const currentDate = new Date();
    const currentYear = currentDate.getFullYear() % 100; 
    const currentMonth = currentDate.getMonth() + 1;

    return year > currentYear || (year === currentYear && month >= currentMonth);
  };

  const validateCVV = (cvv) => {
    return /^\d{3,4}$/.test(cvv); 
  };

  const handlePayment = () => {
    if (paymentMethod === "card") {
      if (!validateCardNumber(formData.cardNumber)) {
        alert("Invalid card number. Must be 13–19 digits.");
        return;
      }
      if (!validateExpiry(formData.expiry)) {
        alert("Invalid expiry date. Use MM/YY and ensure it's in the future.");
        return;
      }
      if (!validateCVV(formData.cvv)) {
        alert("Invalid CVV. Must be 3 or 4 digits.");
        return;
      }
      navigate("/success", { state: location.state });

    } else if (paymentMethod === "upi") {
      if (!formData.upiId.includes("@")) {
        alert("Invalid UPI ID.");
        return;
      }
      navigate("/success", { state: location.state });

    } else if (paymentMethod === "netbanking") {
      if (!formData.bankName || !formData.accountNumber) {
        alert("Please fill all Net Banking details.");
        return;
      }
      navigate("/success", { state: location.state });

    } else {
      alert("Please select a payment method.");
    }
  };

  return (
    <div style={styles.container}>
      <h1>Payment Page</h1>

      {/* Payment Method */}
      <div style={styles.selectWrapper}>
        <select
          value={paymentMethod}
          onChange={(e) => setPaymentMethod(e.target.value)}
          style={styles.select}
        >
          <option value="">Select Payment Method</option>
          <option value="card">Credit/Debit Card</option>
          <option value="upi">UPI</option>
          <option value="netbanking">Net Banking</option>
        </select>
      </div>

      {/* Card Payment */}
      {paymentMethod === "card" && (
        <>
          <input
            type="text"
            name="cardNumber"
            placeholder="Card Number"
            value={formData.cardNumber}
            onChange={handleChange}
            style={styles.input}
          />
          <input
            type="text"
            name="expiry"
            placeholder="Expiry Date (MM/YY)"
            value={formData.expiry}
            onChange={handleChange}
            style={styles.input}
          />
          <input
            type="password"
            name="cvv"
            placeholder="CVV"
            value={formData.cvv}
            onChange={handleChange}
            style={styles.input}
          />
        </>
      )}

      {/* UPI Payment */}
      {paymentMethod === "upi" && (
        <input
          type="text"
          name="upiId"
          placeholder="Enter UPI ID (e.g., name@upi)"
          value={formData.upiId}
          onChange={handleChange}
          style={styles.input}
        />
      )}

      {/* Net Banking */}
      {paymentMethod === "netbanking" && (
        <>
          <input
            type="text"
            name="bankName"
            placeholder="Bank Name"
            value={formData.bankName}
            onChange={handleChange}
            style={styles.input}
          />
          <input
            type="text"
            name="accountNumber"
            placeholder="Account Number"
            value={formData.accountNumber}
            onChange={handleChange}
            style={styles.input}
          />
        </>
      )}

      <button style={styles.button} onClick={handlePayment}>
        Pay & Confirm
      </button>
    </div>
  );
}

const baseFieldStyle = {
  display: "block",
  padding: "12px",
  margin: "10px auto",
  width: "100%",
  fontSize: "16px",
  borderRadius: "6px",
  border: "1px solid #ccc",
  boxSizing: "border-box"
};

const styles = {
  container: {
    maxWidth: "400px",
    margin: "50px auto",
    padding: "25px",
    textAlign: "center",
    border: "1px solid #ccc",
    borderRadius: "12px",
    boxShadow: "0 3px 15px rgba(0,0,0,0.1)",
    backgroundColor: "#fff"
  },
  input: { ...baseFieldStyle },
  selectWrapper: { width: "100%", margin: "10px auto" },
  select: {
    ...baseFieldStyle,
    appearance: "none",
    backgroundColor: "#fff",
    backgroundImage:
      "url('data:image/svg+xml;utf8,<svg fill=%22%23000000%22 height=%2220%22 viewBox=%220 0 24 24%22 width=%2220%22 xmlns=%22http://www.w3.org/2000/svg%22><path d=%22M7 10l5 5 5-5z%22/></svg>')",
    backgroundRepeat: "no-repeat",
    backgroundPosition: "right 10px center",
    backgroundSize: "20px",
    paddingRight: "40px"
  },
  button: {
    padding: "14px 30px",
    fontSize: "18px",
    cursor: "pointer",
    backgroundColor: "#007bff",
    color: "#fff",
    border: "none",
    borderRadius: "6px",
    marginTop: "10px",
    width: "100%"
  }
};

export default PaymentPage;
